import React, { useState, useEffect, useRef } from 'react';
import { Link as ScrollLink } from 'react-scroll';
import {
    Box, Menu, Linkedin, Twitter, Github, Mail, Phone, Facebook, Instagram, Home, Info, Users, Folder, Activity, TrendingUp, Settings, MapPin
} from 'react-feather';
import "./Aiiot_index.css";
//==============================================================================
// 1. CUSTOM HOOK FOR SCROLL ANIMATIONS
//==============================================================================
const useRevealOnScroll = (options) => {
    const [isVisible, setIsVisible] = useState(false);
    const ref = useRef(null);

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                    observer.unobserve(entry.target);
                }
            },
            { threshold: 0.1, ...options }
        );

        const currentRef = ref.current;
        if (currentRef) {
            observer.observe(currentRef);
        }

        return () => {
            if (currentRef) {
                observer.unobserve(currentRef);
            }
        };
    }, [options]);

    return {
        ref: ref,
        className: `reveal-on-scroll ${isVisible ? 'is-visible' : ''}`
    };
};


//==============================================================================
// 2. DATA FOR COMPONENTS
//==============================================================================
const facultyData = [
    { name: 'Dr. Ajay Kumar', role: 'Principal Investigator', img: '/faculties/ajay.jpeg', link: 'https://www.adishankara.ac.in/department/faculty/25', description: 'Dr. Ajay Kumar is an Associate Professor at ASIET with a PhD in Electronics and Communication Engineering. His research interests include IoT and Wireless Sensor Networks.' },
    { name: 'Mr. Albins Paul', role: 'Co-Investigator', img: '/faculties/albins.jpg', link: 'https://www.adishankara.ac.in/department/faculty/66', description: "Assistant Professor at ASIET's ECE Department, specializing in Microwave & Television Engineering." },
    { name: 'Prof. P.V. Rajaraman', role: 'Co-Investigator', img: '/faculties/rajaraman.jpg', link: 'https://www.adishankara.ac.in/department/faculty/375', description: 'Assistant Professor, CTO, and Head of the AI Department at ASIET. He specializes in NLP and XAI, has multiple publications, and is currently pursuing his Ph.D.' },
    { name: 'Mr. Abhijith Pm', role: 'Project Associate', img: '/faculties/abhijith.jpeg', link: 'https://www.linkedin.com/in/abhijithpm-embedded-engineer/?originalSubdomain=in' },
    { name: 'Mrs. Hasna Hameed', role: 'Project Associate', img: '/faculties/hasna2.JPG', link: 'https://www.linkedin.com/in/hasna-hameed-31b0b6227/' },
    { name: 'Ms. Arathy Surendran', role: 'Project Assistant', img: '/faculties/arathy.JPG', link: 'https://www.linkedin.com/in/arathy-surendran/' },
    { name: 'Mr. Bhagyaraj J', role: 'Project Assistant', img: '/faculties/bhagyaraj.jpeg', link: '#' },
    { name: 'Mr. Amaljith N Raj', role: 'Project Assistant', img: '/faculties/amaljith.JPG', link: '#' },
    { name: 'Mrs. Jebina EA', role: 'Project Assistant', img: '/faculties/jibinaea.jpeg', link: '#' },
];

const projectData = [
    { title: 'Intelligent Sensor Module', img: '/sensor_modules/module3.jpg', description: 'Developing a smart sensor module for real-time monitoring and management of environmental pollutants.' },
    { title: 'Smart Water Level Monitoring', img: '/sensor_modules/water.png', description: 'A robust solution for monitoring water levels with an integrated alert system to mitigate flood risks.' },
    { title: 'Digital Water Distribution', img: '/sensor_modules/water_authorityy.jpeg', description: 'Creating a digital twin to efficiently monitor and manage water distribution networks in urban areas.' },
    { title: 'Startup & Skill Development', img: '/sensor_modules/skill.jpg', description: 'Fostering a vibrant startup ecosystem and providing skill development programs centered around our IoT solutions.' },
    { title: 'Explainable AI Software', img: '/sensor_modules/ai.jpeg', description: 'Building analysis software based on Explainable AI (XAI) to bring transparency and trust to complex IoT systems.' },
];


//==============================================================================
// 3. SECTION COMPONENTS
//==============================================================================

const Header = () => {
    const navLinks = [
        { id: 'about', title: 'About' },
        { id: 'faculty', title: 'Faculty' },
        { id: 'projects', title: 'Projects' },
        { id: 'contact', title: 'Contact' },
    ];
    return (
        <header className="sticky top-0 z-50 w-full bg-white/80 backdrop-blur-lg border-b border-slate-200/80">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <nav className="flex justify-between items-center h-16">
                    <a href="#" className="flex items-center gap-2 text-xl md:text-2xl font-bold text-blue-600">
                        <Box size={28} />
                        <span className="hidden sm:inline">Center for AI-IoT Innovation</span>
                        <span className="sm:hidden">AI-IoT Center</span>
                    </a>
                    <div className="hidden md:flex items-center space-x-4">
                        <ul className="flex items-center space-x-8">
                            {navLinks.map(link => (
                                <li key={link.id}>
                                    <ScrollLink to={link.id} spy={true} smooth={true} offset={-70} duration={500} className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300">
                                        {link.title}
                                    </ScrollLink>
                                </li>
                            ))}
                        </ul>
                        <div className="flex items-center space-x-2">
                           <a href="https://airaware-app-gcw7.onrender.com/" target="_blank" rel="noopener noreferrer" className="bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:shadow-lg transition duration-300 transform hover:-translate-y-0.5">AirAware</a>
                           <a href="https://app.aiiot.it.com/aws" target="_blank" rel="noopener noreferrer" className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:shadow-lg transition duration-300 transform hover:-translate-y-0.5">AWS</a>
                        </div>
                    </div>
                    <button className="md:hidden text-slate-600 hover:text-blue-600" aria-label="Open menu"><Menu /></button>
                </nav>
            </div>
        </header>
    );
};

const Hero = () => {
    const [images, setImages] = useState([]);
    const [currentIndex, setCurrentIndex] = useState(0);
    const intervalRef = useRef(null);
    const revealTitleProps = useRevealOnScroll();
    const revealTextProps = useRevealOnScroll();
    const revealButtonsProps = useRevealOnScroll();
    const revealImageProps = useRevealOnScroll();

    useEffect(() => {
        fetch('/carousel-images/carousel-images.json')
            .then(res => res.json())
            .then(data => setImages(data))
            .catch(err => console.error("Could not load carousel images:", err));
    }, []);

    const startAutoSlide = () => {
        clearInterval(intervalRef.current);
        if (images.length > 0) {
            intervalRef.current = setInterval(() => {
                setCurrentIndex(prevIndex => (prevIndex + 1) % images.length);
            }, 4000);
        }
    };

    useEffect(() => {
        startAutoSlide();
        return () => clearInterval(intervalRef.current);
    }, [images.length]);
    
    if (images.length === 0) return null;

    return (
        <section id="hero" className="relative py-20 md:py-32" style={{ background: 'linear-gradient(135deg, rgba(255, 255, 255, 1) 0%, rgba(240, 245, 255, 1) 100%)' }}>
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
                <h1 {...revealTitleProps} className="text-4xl md:text-6xl font-extrabold text-slate-800 mb-4 leading-tight">
                    <span className="block text-2xl md:text-4xl font-medium text-slate-600">Sponsored by</span>
                    <span className="text-blue-600">Ministry of Electronics and Information Technology</span>
                </h1>
                <p {...revealTextProps} className="text-lg md:text-xl text-slate-600 mb-10 max-w-3xl mx-auto" style={{ transitionDelay: '150ms' }}>
                    The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI).
                </p>
                <div {...revealButtonsProps} className="flex flex-col sm:flex-row justify-center items-center gap-4 mb-12" style={{ transitionDelay: '300ms' }}>
                    <ScrollLink to="projects" smooth={true} offset={-70} duration={500} className="cursor-pointer w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-lg shadow-lg transition duration-300 transform hover:scale-105">Explore Projects</ScrollLink>
                    <ScrollLink to="about" smooth={true} offset={-70} duration={500} className="cursor-pointer w-full sm:w-auto bg-white hover:bg-slate-100 text-slate-800 font-bold py-3 px-8 rounded-lg border border-slate-300 shadow-md transition duration-300 transform hover:scale-105">Learn More</ScrollLink>
                </div>
                <div {...revealImageProps} className="relative max-w-5xl mx-auto" style={{ transitionDelay: '450ms' }}>
                    <div className="absolute -inset-2 bg-gradient-to-r from-blue-400 to-indigo-500 rounded-2xl blur-lg opacity-25"></div>
                    <div className="relative w-full h-auto overflow-hidden rounded-xl shadow-2xl">
                        <img src={images[currentIndex].src} alt={images[currentIndex].alt} className="w-full h-auto object-cover transition-opacity duration-1000 ease-in-out" />
                    </div>
                    <div className="flex justify-center mt-6 space-x-3">
                        {images.map((_, index) => (
                            <div key={index} onClick={() => { setCurrentIndex(index); startAutoSlide(); }} className={`w-3 h-3 rounded-full cursor-pointer transition-all duration-300 ${currentIndex === index ? 'bg-blue-600 scale-125' : 'bg-blue-300'}`}></div>
                        ))}
                    </div>
                </div>
            </div>
        </section>
    );
};

const About = () => {
    const revealHeadingProps = useRevealOnScroll();
    const revealImageProps = useRevealOnScroll();
    const revealTextProps = useRevealOnScroll();
    return (
        <section id="about" className="py-20 bg-white">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div {...revealHeadingProps} className="text-center mb-12">
                    <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">About Our Center</h2>
                    <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">Pioneering research where intelligence meets connectivity.</p>
                </div>
                <div className="grid md:grid-cols-2 gap-12 items-center">
                    <div {...revealImageProps}>
                        <div className="rounded-xl overflow-hidden shadow-lg border border-slate-200">
                            <img src="/.jpg" alt="Collaborative team lab" loading="lazy" className="w-full h-auto object-cover" />
                        </div>
                    </div>
                    <div {...revealTextProps} className="text-lg text-slate-600 space-y-6" style={{ transitionDelay: '150ms' }}>
                        <p>The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI). The lab is equipped with hardware development tools, computing systems, and educational resources to support research and development in this area.</p>
                        <p>We provide a state-of-the-art environment equipped with powerful computing resources and hardware development tools. This fosters a culture of innovation, empowering researchers and students to build the next generation of smart solutions.</p>
                    </div>
                </div>
            </div>
        </section>
    );
};

const Faculty = () => {
    const revealHeadingProps = useRevealOnScroll();
    return (
        <section id="faculty" className="py-20 bg-slate-50">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div {...revealHeadingProps} className="text-center mb-12">
                    <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">Meet Our Expert Faculty</h2>
                    <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">The brilliant minds leading our research and innovation.</p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
                    {facultyData.map((person, index) => <FacultyCard key={index} person={person} delay={index * 150} />)}
                </div>
            </div>
        </section>
    );
};

const FacultyCard = ({ person, delay }) => {
    const revealCardProps = useRevealOnScroll();
    return (
        <div {...revealCardProps} style={{ transitionDelay: `${delay}ms` }} className="text-center bg-white p-6 rounded-xl shadow-md border border-slate-200 transform transition duration-300 hover:-translate-y-2 hover:shadow-xl">
            <a href={person.link} target="_blank" rel="noopener noreferrer" className="block">
                <img className="w-32 h-32 mx-auto rounded-full mb-4 object-cover shadow-lg" src={person.img} alt={`Photo of ${person.name}`} loading="lazy" onError={(e) => { e.target.onerror = null; e.target.src='https://placehold.co/128x128/e0e0e0/000000?text=Faculty'; }} />
            </a>
            <a href={person.link} target="_blank" rel="noopener noreferrer" className="hover:text-blue-800 transition duration-300">
                <h4 className="text-xl font-bold text-blue-700">{person.name}</h4>
            </a>
            <p className="text-slate-500 font-medium mb-2">{person.role}</p>
            {person.description && <p className="text-slate-600 text-sm mb-4">{person.description}</p>}
            {!person.description && <div className="h-10 mb-4"></div>}
            <div className="flex justify-center space-x-4">
                <a href={person.link.includes('linkedin') ? person.link : '#'} target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-500"><Linkedin /></a>
                <a href="#" target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-500"><Twitter /></a>
            </div>
        </div>
    );
};

const Projects = () => {
    const revealHeadingProps = useRevealOnScroll();
    return (
        <section id="projects" className="py-20 bg-white">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div {...revealHeadingProps} className="text-center mb-12">
                    <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">Our Ongoing Projects</h2>
                    <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">From concept to reality, we're building solutions that matter.</p>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {projectData.map((project, index) => <ProjectCard key={index} project={project} delay={index * 100} />)}
                </div>
            </div>
        </section>
    );
};

const ProjectCard = ({ project, delay }) => {
    const revealCardProps = useRevealOnScroll();
    return (
        <div {...revealCardProps} style={{ transitionDelay: `${delay}ms` }} className="bg-white p-6 rounded-xl shadow-md border border-slate-200 transform transition duration-300 hover:-translate-y-2 hover:shadow-xl">
            <img src={project.img} alt={project.title} className="w-full h-40 object-cover rounded-lg mb-4" loading="lazy" />
            <h4 className="text-xl font-bold text-blue-700 mb-2">{project.title}</h4>
            <p className="text-slate-600 text-sm">{project.description}</p>
        </div>
    );
};

const Contact = () => {
    const revealProps = useRevealOnScroll();
    return (
        <section id="contact" className="py-20 bg-slate-50">
            <div {...revealProps} className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
                <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800 mb-4">Let's Build the Future Together</h2>
                <p className="text-lg text-slate-600 mb-8">Have a project in mind, a question, or want to collaborate? We'd love to hear from you.</p>
                <div className="flex flex-col sm:flex-row justify-center items-center gap-6">
                    <a href="mailto:aiiot@adishankara.ac.in" className="flex items-center justify-center gap-3 w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-lg shadow-lg transition duration-300 transform hover:scale-105"><Mail className="w-5 h-5" /> Email Us</a>
                    <a href="tel:+919846900310" className="flex items-center justify-center gap-3 w-full sm:w-auto bg-slate-100 hover:bg-slate-200 text-slate-800 font-bold py-3 px-8 rounded-lg border border-slate-300 shadow-md transition duration-300 transform hover:scale-105"><Phone className="w-5 h-5" /> Call +919846900310</a>
                </div>
            </div>
        </section>
    );
};

const Footer = () => {
    return (
        <footer className="bg-slate-800 text-slate-400">
            <div className="max-w-7xl mx-auto py-12 px-4 sm:px-6 lg:px-8">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                    <div className="space-y-4">
                        <div className="flex items-center gap-2 text-xl font-bold text-white mb-4"><Box /><span>AI-IoT</span></div>
                        <div className="flex space-x-4 pt-2">
                            <a href="#" className="text-slate-400 hover:text-blue-400"><Facebook className="w-5 h-5" /></a>
                            <a href="#" className="text-slate-400 hover:text-blue-400"><Twitter className="w-5 h-5" /></a>
                            <a href="#" className="text-slate-400 hover:text-blue-400"><Linkedin className="w-5 h-5" /></a>
                            <a href="#" className="text-slate-400 hover:text-blue-400"><Instagram className="w-5 h-5" /></a>
                        </div>
                    </div>
                    <div>
                        <h4 className="text-lg font-semibold text-white">Quick Links</h4>
                        <ul className="space-y-2 mt-4">
                            <li><ScrollLink to="hero" smooth={true} duration={500} className="cursor-pointer text-sm hover:text-blue-400 flex items-center gap-2"><Home className="w-4 h-4" /> Home</ScrollLink></li>
                            <li><ScrollLink to="about" smooth={true} offset={-70} duration={500} className="cursor-pointer text-sm hover:text-blue-400 flex items-center gap-2"><Info className="w-4 h-4" /> About Us</ScrollLink></li>
                            <li><ScrollLink to="faculty" smooth={true} offset={-70} duration={500} className="cursor-pointer text-sm hover:text-blue-400 flex items-center gap-2"><Users className="w-4 h-4" /> Faculty</ScrollLink></li>
                            <li><ScrollLink to="projects" smooth={true} offset={-70} duration={500} className="cursor-pointer text-sm hover:text-blue-400 flex items-center gap-2"><Folder className="w-4 h-4" /> Projects</ScrollLink></li>
                            <li><ScrollLink to="contact" smooth={true} offset={-70} duration={500} className="cursor-pointer text-sm hover:text-blue-400 flex items-center gap-2"><Phone className="w-4 h-4" /> Contact</ScrollLink></li>
                        </ul>
                    </div>
                     <div>
                        <h4 className="text-lg font-semibold text-white">Services</h4>
                        <ul className="space-y-2 mt-4">
                            <li><a href="#" className="text-sm hover:text-blue-400 flex items-center gap-2"><Activity className="w-4 h-4" /> IoT Monitoring</a></li>
                            <li><a href="#" className="text-sm hover:text-blue-400 flex items-center gap-2"><TrendingUp className="w-4 h-4" /> Predictive Models</a></li>
                            <li><a href="#" className="text-sm hover:text-blue-400 flex items-center gap-2"><Settings className="w-4 h-4" /> System Integration</a></li>
                        </ul>
                    </div>
                    <div>
                        <h4 className="text-lg font-semibold text-white">Contact Information</h4>
                        <div className="space-y-2 mt-4 text-sm">
                            <p className="flex items-start gap-2"><MapPin className="w-4 h-4 mt-0.5 flex-shrink-0" /><span>Adi Shankara Institute of Engineering and Technology<br />Kalady 683574, Ernakulam<br />Kerala, India</span></p>
                            <p className="flex items-center gap-2"><Mail className="w-4 h-4" /><a href="mailto:aiiot@adishankara.ac.in" className="hover:text-blue-400">aiiot@adishankara.ac.in</a></p>
                            <p className="flex items-center gap-2"><Phone className="w-4 h-4" /><a href="tel:04842463825" className="hover:text-blue-400">0484 246 3825</a></p>
                        </div>
                    </div>
                </div>
                <div className="border-t border-slate-700 mt-8 pt-8 text-center">
                    <p className="text-sm">&copy; 2025 Center for AI-IoT Innovation. All Rights Reserved.</p>
                    <p className="mt-2 text-xs text-slate-500">Designed for a smarter, more connected future.</p>
                </div>
            </div>
        </footer>
    );
};


//==============================================================================
// 4. MAIN EXPORTED COMPONENT
//==============================================================================
const AiIotInnovationCenter = () => {
    return (
        <>
            <Header />
            <main className="flex-grow">
                <Hero />
                <About />
                <Faculty />
                <Projects />
                <Contact />
            </main>
            <Footer />
        </>
    );
};

export default AiIotInnovationCenter;
